import { evaluateGatingPolicy, fetchWorkflowRunsFromApi } from './scripts/verify-ci-gating.mjs';
const quiet={log(){},error(){},warn(){}};const sha='1'.repeat(40);const repo='OneITB/OneITB23';const latest={id:102,run_attempt:1,head_sha:sha,head_branch:'main',status:'completed',conclusion:'failure',head_repository:{full_name:repo}};
let fetchCalls=0;const stale=await evaluateGatingPolicy({env:{GITHUB_EVENT_NAME:'workflow_run',GITHUB_REPOSITORY:repo,WORKFLOW_RUN_HEAD_SHA:sha,WORKFLOW_RUN_CONCLUSION:'success',WORKFLOW_RUN_BRANCH:'main',WORKFLOW_RUN_REPO:repo},fetchRuns:async()=>{fetchCalls++;return [latest]},logger:quiet});
const manual=await evaluateGatingPolicy({env:{GITHUB_EVENT_NAME:'workflow_dispatch',GITHUB_REPOSITORY:repo,GITHUB_REF:'refs/heads/feature/example',INPUT_TARGET_SHA:sha},fetchRuns:async()=>[{...latest,conclusion:'success'}],logger:quiet});
let suppliedSignal=false;globalThis.fetch=async(url,options)=>{suppliedSignal=!!options.signal;return {ok:true,json:async()=>({workflow_runs:[]})}};await fetchWorkflowRunsFromApi(repo,sha,'');
console.log(JSON.stringify({staleWorkflowRun:{result:stale,fetchCalls},manualFeatureContext:manual,httpRequestHasAbortSignal:suppliedSignal},null,2));
